writing.exampleCode:
-- PostgreSQL SQL; the events table already exists.
CREATE INDEX events_tenant_kind_at ON events (tenant_id, kind, at);
EXPLAIN SELECT tenant_id, kind, at
FROM events
WHERE kind = 'click' AND at > TIMESTAMP '2026-10-01';

